create function private.validate_response(q jsonb,r jsonb)returns void language plpgsql immutable set search_path='' as $$declare k text;v jsonb;begin if r is null or r='null'::jsonb then return;end if;
if q->>'type'='mcq'then if jsonb_typeof(r)is distinct from 'string'or not exists(select 1 from jsonb_array_elements(q->'options')o where o->'id'=r)then raise exception 'INVALID_RESPONSE';end if;
elsif q->>'type'='boolean'then if jsonb_typeof(r)is distinct from 'boolean'then raise exception 'INVALID_RESPONSE';end if;
elsif q->>'type'='subjective'then if jsonb_typeof(r)is distinct from 'string'or length(r#>>'{}')>30000 then raise exception 'INVALID_RESPONSE';end if;
else if jsonb_typeof(r)is distinct from 'object'then raise exception 'INVALID_RESPONSE';end if;for k,v in select key,value from jsonb_each(r)loop if jsonb_typeof(v)is distinct from 'string'or length(v#>>'{}')>4000 then raise exception 'INVALID_RESPONSE';end if;if q->>'type'='blank'then if not exists(select 1 from jsonb_array_elements_text(q->'blanks')x where x=k)then raise exception 'INVALID_RESPONSE';end if;else if not exists(select 1 from jsonb_array_elements(q->'left')x where x->>'id'=k)or(v<>'""'::jsonb and not exists(select 1 from jsonb_array_elements(q->'right')x where x->'id'=v))then raise exception 'INVALID_RESPONSE';end if;end if;end loop;end if;end$$;
revoke execute on function private.validate_response(jsonb,jsonb)from public,anon,authenticated;
create function private.normalize_roster()returns trigger language plpgsql set search_path='' as $$begin new.roll:=lower(trim(new.roll));if length(new.roll)=0 then raise exception 'ROLL_REQUIRED';end if;return new;end$$;
create trigger normalize_roll before insert or update on public.enrollments for each row execute function private.normalize_roster();
